# C:\IOTEC\099_PAYMENT_HUB.pyimport sysimport subprocessdef exibir_carteira_de_pagamento(item, qtd, valor, cliente, cpf):    print("=" * 60)    print("        NÚCLEO IOTEC/X27 - CARTEIRA DE PAGAMENTOS        ")    print("=" * 60)    print(f" PRODUTO/SERVIÇO : {item} (x{qtd})")    print(f" TOTAL A PAGAR   : R$ {qtd * valor:.2f}")    print(f" CLIENTE         : {cliente} ({cpf})")    print("-" * 60)    print(" ESCOLHA A FORMA DE PAGAMENTO:")    print(" [1] PayPal (Cartão de Crédito / Débito Internacional)")    print(" [2] PicPay (Pix / Saldo PicPay)")    print(" [3] Outros Métodos (Em breve...)")    print("=" * 60)        opcao = input(" Selecione a opção (1 ou 2): ").strip()        if opcao == "1":        print("\n[IOTEC HUB] Redirecionando para o Gateway PayPal...")        # Chama o nosso gateway PayPal discriminado já pronto        cmd = [            "python", r"C:\IOTEC\099H_PAYPAL_PIX_GATEWAY.py",            "--item", item,            "--qtd", str(qtd),            "--valor", str(valor),            "--cliente", cliente,            "--cpf", cpf        ]        subprocess.run(cmd)    elif opcao == "2":        print("\n[IOTEC HUB] Inicializando Gateway PicPay...")        # Aqui entra a chamada do script 099L_PICPAY_GATEWAY.py        print("[EM DESENVOLVIMENTO]: Módulo PicPay pronto para ser acoplado.")    else:        print("\n[ERRO]: Opção inválida. Selecione um método ativo da carteira.")if __name__ == "__main__":    exibir_carteira_de_pagamento(        item="Consultoria e Ativacao do Nucleo X27",        qtd=1,        valor=150.00,        cliente="Carlos Eduardo Silva",        cpf="123.456.789-00"    )